import json
with open('issue-319.jsonl') as f:
    lines = [json.loads(l) for l in f if l.strip()]

def get_ts(l):
    return l.get('timestamp')

out = []
for l in lines:
    t = l.get('type')
    ts = get_ts(l)
    if t == 'user':
        msg = l.get('message', {})
        content = msg.get('content')
        if isinstance(content, str):
            out.append((ts, 'USER', content[:500]))
        elif isinstance(content, list):
            for c in content:
                if c.get('type') == 'text':
                    out.append((ts, 'USER', c['text'][:500]))
                elif c.get('type') == 'tool_result':
                    cc = c.get('content')
                    if isinstance(cc, list):
                        txt = ' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                    else:
                        txt = str(cc)
                    out.append((ts, 'TOOL_RESULT', txt[:300]))
    elif t == 'assistant':
        msg = l.get('message', {})
        content = msg.get('content')
        if isinstance(content, list):
            for c in content:
                if c.get('type') == 'text':
                    out.append((ts, 'ASSISTANT', c['text'][:500]))
                elif c.get('type') == 'tool_use':
                    out.append((ts, 'TOOL_USE:'+c.get('name',''), json.dumps(c.get('input',{}))[:300]))
print(len(out))
for o in out[100:180]:
    print(o[0], '|', o[1], '|', o[2].replace(chr(10),' '))
"

